__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"default",{enumerable:!0,get:function(){return o}});var o={tela:{titulo:'\xbfSab\xedas?',subtitulo:'Siete preguntas por d\xeda \u2014 el mito cae, la fuente queda',contador:(o,n)=>`Pregunta ${o} de ${n}`,certo:'\xa1En la fuente correcta!',errado:'No fue esta vez \u2014 la correcta est\xe1 marcada.',fontePrefixo:'Fuente: ',proxima:'Siguiente pregunta',verPlacar:'Ver marcador',placarTitulo:'Ronda de hoy',placarDe:(o,n)=>`${o} de ${n}`,acumulado:(o,n)=>`En total ya respondiste ${o} pregunta${1===o?'':'s'} \u2014 ${n} en la fuente correcta.`,amanha:'Ma\xf1ana hay siete nuevas. La ronda cambia con el d\xeda \u2014 y es la misma para todo el mundo, as\xed que se puede comparar.',rodadaFeitaAviso:'Ya hiciste la ronda de hoy.',a11yOpcao:o=>`Alternativa ${o}`},temas:{taro:'Tarot',lua:'Luna',historia:'Historia'},placar:['Ronda limpia: siete de siete en la fuente correcta. Esas son exactamente las historias que circulan mal por ah\xed \u2014 y las acabas de comprobar todas en el recibo.','Casi todo en la fuente correcta. Las que se escaparon quedaron con la explicaci\xf3n y el recibo justo arriba \u2014 y ma\xf1ana hay siete m\xe1s.','Mitad y mitad \u2014 y tiene sentido: buena parte de esas historias circula mal desde hace d\xe9cadas, con fecha y autor del error. Ahora sabes d\xf3nde comprobar.','Las respuestas "obvias" de este quiz son justamente las que el mercado repite sin fuente. Cada explicaci\xf3n de arriba cuenta la historia real, con autor y fecha \u2014 y ma\xf1ana hay revancha.'],perguntas:{'taro-leitura-nascimento':{pergunta:'\xbfCu\xe1ndo naci\xf3 el tarot como lectura del futuro?',opcoes:['En el antiguo Egipto, con el Libro de Thoth','En la Italia del siglo XV, junto con las cartas','En el siglo XVIII \u2014 antes de eso, el tarot era solo un juego','En la Grecia cl\xe1sica, en los templos oraculares'],explicacao:'La baraja existe desde la Italia del siglo XV \u2014 pero pas\xf3 unos 350 a\xf1os siendo juego de apuesta y de sal\xf3n, y todav\xeda se juega hoy en Francia y en Austria. La lectura m\xe1s antigua documentada es una hoja bolo\xf1esa de antes de 1750, y el primer m\xe9todo publicado es de Etteilla, en 1783. Resumen honesto: seis siglos de imagen, dos siglos y medio de lectura.',fonte:'Hoja bolo\xf1esa (antes de 1750), hallada por Franco Pratesi \xb7 Etteilla, primer m\xe9todo publicado, 1783'},'taro-egito-autor':{pergunta:'\xbfQui\xe9n invent\xf3 la historia de que el tarot viene de Egipto?',opcoes:['Sacerdotes egipcios, en papiros del templo','Antoine Court de G\xe9belin, en un libro de 1781','Los primeros fabricantes de cartas italianos','Aleister Crowley, en 1944'],explicacao:'Court de G\xe9belin vio una partida de tarot en una reuni\xf3n social en Par\xeds, crey\xf3 reconocer s\xedmbolos egipcios y public\xf3 que era el Libro de Thoth \u2014 sin presentar un solo documento. El detalle que lo derrumba todo: escribi\xf3 eso en 1781, y nadie en el mundo le\xeda egipcio antes de que Champollion descifrara los jerogl\xedficos, en 1822.',fonte:'Antoine Court de G\xe9belin, Le Monde primitif, vol. 8, "Du Jeu des Tarots", 1781'},'taro-waite-refuta':{pergunta:'\xbfQu\xe9 escribi\xf3 Waite \u2014 autor de la baraja m\xe1s vendida del mundo \u2014 en 1911 sobre el origen egipcio del tarot?',opcoes:['Que no hay "una part\xedcula de evidencia" a su favor','Que era el mayor secreto de la baraja','Que solo los iniciados pod\xedan confirmarlo','Que los faraones lo dejaron grabado en los templos'],explicacao:'Waite dedica una secci\xf3n entera del Pictorial Key a desmontar a Court de G\xe9belin: llama a sus diez argumentos "pilares de arena" y recuerda que la etimolog\xeda egipcia se propuso cuando nadie sab\xeda leer egipcio. Quien dice que el tarot no viene de Egipto est\xe1 del lado del autor de la baraja \u2014 no en su contra.',fonte:'A. E. Waite, The Pictorial Key to the Tarot, Parte I \xa74, 1911'},'taro-quem-desenhou':{pergunta:'\xbfQui\xe9n dibuj\xf3 las 78 cartas de la famosa "baraja de Waite", lanzada en diciembre de 1909?',opcoes:['El propio A. E. Waite','\xc9liphas L\xe9vi','Una imprenta an\xf3nima de Londres','La artista Pamela Colman Smith'],explicacao:'Waite encarg\xf3 y dirigi\xf3, pero quien dibuj\xf3 carta por carta fue Pamela Colman Smith \u2014 por eso el nombre justo es Rider-Waite-Smith. Para las 56 cartas menores, Smith se apoy\xf3 en el Sola Busca, una baraja italiana de cerca de 1491 cuyas fotos acababan de entrar en el British Museum, en 1907.',fonte:'Baraja Waite-Smith, dic./1909 \xb7 A. E. Waite, The Pictorial Key to the Tarot, 1911'},'taro-estrela':{pergunta:'En la lista de significados de Waite (1911), la carta de la Estrella quiere decir, en primer lugar...',opcoes:['Esperanza y futuro brillante','Un viaje largo por mar','P\xe9rdida, robo, privaci\xf3n, abandono','Reencuentro con un amor antiguo'],explicacao:'Es el caso m\xe1s chocante de la lista: Waite escribe "Loss, theft, privation, abandonment" \u2014 y solo despu\xe9s anota que "otra lectura dice: esperanza y buenas perspectivas". La lectura moderna invirti\xf3 la prioridad siguiendo la imagen de Smith, no el texto de Waite: las dos mitades de la baraja nunca contaron la misma historia.',fonte:'A. E. Waite, The Pictorial Key to the Tarot, 1911 \u2014 carta XVII, La Estrella'},'taro-morte':{pergunta:'Y la carta de la Muerte, en esa misma lista de Waite (1911), significa...',opcoes:['Nunca significa muerte, solo recomienzo','"Fin, mortalidad, destrucci\xf3n"','Herencia inesperada','Una boda cercana'],explicacao:'La lectura "transformaci\xf3n" es una elecci\xf3n \xe9tica del siglo XX \u2014 leg\xedtima, y es la que usa esta app \u2014, pero no estaba ah\xed al comienzo: Waite escribe "End, mortality, destruction, corruption". Saber qu\xe9 escribi\xf3 el autor y qu\xe9 eligi\xf3 despu\xe9s la pr\xe1ctica ya es la mitad del camino para leer tarot sin repetir leyendas.',fonte:'A. E. Waite, The Pictorial Key to the Tarot, 1911 \u2014 carta XIII'},'taro-cruz-celta':{pergunta:'\xbfLa tirada "Cruz Celta" es celta?',opcoes:['S\xed \u2014 viene de los druidas de Irlanda','S\xed \u2014 est\xe1 en manuscritos medievales','No \u2014 es egipcia, a pesar del nombre','No \u2014 el nombre es de Waite, en 1911'],explicacao:'El nombre aparece por primera vez en el libro de Waite, que solo dice que el m\xe9todo "se usaba en privado desde hac\xeda muchos a\xf1os". La estructura viene de los c\xedrculos de la Golden Dawn de los a\xf1os 1890 \u2014 ninguna atestaci\xf3n celta, ning\xfan druida en el proceso.',fonte:'A. E. Waite, The Pictorial Key to the Tarot, Parte III \xa77, 1911'},'taro-tres-cartas':{pergunta:'\xbfDe d\xf3nde viene la tirada de tres cartas Pasado / Presente / Futuro?',opcoes:['Nadie encontr\xf3 fuente primaria \u2014 se populariz\xf3 en el siglo XX','Del Pictorial Key de Waite','De la Golden Dawn','De los templos de Egipto'],explicacao:'Waite da tres m\xe9todos en el libro \u2014 de 10, 42 y 35 cartas \u2014 y ninguno es un tres-cartas temporal; la Golden Dawn usaba otra tirada, la Opening of the Key, una operaci\xf3n de horas. La tirada de tres es leg\xedtima como pr\xe1ctica \u2014 lo que no se puede es llamarla "la cl\xe1sica", porque nadie encontr\xf3 el texto que la funda.',fonte:'Verificado en A. E. Waite, The Pictorial Key to the Tarot, 1911 \u2014 la tirada no est\xe1 ah\xed'},'taro-invertidas':{pergunta:'\xbfQui\xe9n fue el primero en publicar significados de carta invertida, uno por carta?',opcoes:['Los fabricantes de Marsella','Waite, en 1911','Etteilla, a partir de 1770','Una tradici\xf3n oral milenaria, sin registro escrito'],explicacao:'Etteilla instituy\xf3 el significado invertido sistem\xe1tico \u2014 toda lectura de invertida en el mundo desciende de \xe9l. Y hay sorpresa en Waite: ah\xed la invertida suele ser un sentido lateral, a veces mejor que el derecho \u2014 la Rueda de la Fortuna al rev\xe9s pasa a ser "aumento, abundancia".',fonte:'Etteilla, primer manual de cartomancia con invertidas, 1770 \xb7 Waite, 1911'},'taro-78-cartas':{pergunta:'\xbfTodo tarot tiene 78 cartas?',opcoes:['S\xed \u2014 es n\xfamero fijado desde el origen','No \u2014 la Minchiate de Florencia tiene 97; el Bolo\xf1\xe9s, 62','S\xed \u2014 78 es la suma de las letras hebreas','No \u2014 el n\xfamero cambia cada siglo'],explicacao:'El 78 es el patr\xf3n que gan\xf3, no una ley: la Minchiate florentina tiene 97 cartas, el Tarocco Bolognese tiene 62 y el Siciliano, 64. De paso, eso desmonta la numerolog\xeda de las "22 l\xe1minas = 22 letras hebreas" \u2014 los patrones hist\xf3ricos no siempre tienen 22 triunfos.',fonte:'Patrones italianos hist\xf3ricos (Minchiate, Bolognese, Siciliano) \u2014 Dummett, The Game of Tarot, 1980'},'taro-marselha':{pergunta:'\xbfEl "Tarot de Marsella" es el tarot m\xe1s antiguo que existe?',opcoes:['No \u2014 los m\xe1s antiguos son italianos, pintados a mano en el siglo XV','S\xed \u2014 fue dise\xf1ado en Marsella en el siglo XII','S\xed \u2014 lleg\xf3 en las naves fenicias','No \u2014 es copia de la baraja de Waite'],explicacao:'Los tarots m\xe1s antiguos que sobrevivieron son los italianos pintados a mano, como los Visconti-Sforza de mediados del siglo XV. El patr\xf3n "de Marsella" es impresi\xf3n francesa posterior (Noblet c. 1650, Conver 1760) \u2014 y el nombre comercial "Ancien Tarot de Marseille" lo populariz\xf3 Paul Marteau, de la editorial Grimaud, en 1930.',fonte:'Paul Marteau / Grimaud, Ancien Tarot de Marseille, 1930'},'lua-superlua':{pergunta:'\xbfQui\xe9n invent\xf3 la palabra "Superluna"?',opcoes:['La NASA, en la era Apolo','Galileo, al apuntar el telescopio','Los almanaques coloniales estadounidenses','El astr\xf3logo Richard Nolle, en una revista de 1979'],explicacao:'"Superluna" parece t\xe9rmino de observatorio, pero naci\xf3 en una revista de hor\xf3scopo: Richard Nolle acu\xf1\xf3 el nombre en Dell Horoscope en 1979, y la prensa solo lo adopt\xf3 en masa en 2011. El nombre t\xe9cnico es perigee syzygy \u2014 y la diferencia de tama\xf1o, real (~14%), es imperceptible a simple vista sin una foto lado a lado.',fonte:'Richard Nolle, revista Dell Horoscope, 1979'},'lua-cheia-lavoura':{pergunta:'\xbfLa Luna Llena era \xe9poca de qu\xe9 en el campo romano?',opcoes:['De cosechar todo lo que estaba maduro','De sembrar habas','De cortar madera','De esquilar las ovejas'],explicacao:'Es lo contrario de lo que se repite por ah\xed: cosechar, cortar y esquilar era trabajo de menguante \u2014 Plinio anota que as\xed la planta "sufre menos da\xf1o". En la llena, Columela mandaba sembrar habas. La regla del campo era: creciente para poner, menguante para sacar \u2014 y las habas en la v\xedspera de la llena era la instrucci\xf3n espec\xedfica de Columela.',fonte:'Columela, De Re Rustica XI.2.85, siglo I \xb7 Plinio el Viejo, Naturalis Historia XVIII.321, siglo I'},'lua-nomes-almanaque':{pergunta:'"Luna del Lobo", "Luna de la Fresa", "Luna de Nieve" \u2014 \xbfde d\xf3nde vienen esos nombres?',opcoes:['De los pueblos ind\xedgenas del Amazonas','De la mitolog\xeda griega','De almanaques agr\xedcolas de EE. UU., en los a\xf1os 1930','De los druidas celtas'],explicacao:'La lista est\xe1ndar sali\xf3 de un almanaque agr\xedcola estadounidense: el Maine Farmers\' Almanac public\xf3 los nombres en los a\xf1os 1930, y el Old Farmer\'s Almanac lo simplific\xf3 a un nombre por mes. Es una mezcla de fuentes algonquinas, inglesas y celtas vendida como sistema \xfanico \u2014 y describe el ciclo agr\xedcola del noreste de EE. UU.: al sur del ecuador, "Luna de Nieve" en febrero cae en pleno verano.',fonte:'Maine Farmers\' Almanac, a\xf1os 1930 \xb7 primera lista impresa: Daniel Carter Beard, 1918'},'lua-rosa':{pergunta:'En abril, \xbfla "Luna Rosa" se pone rosa?',opcoes:['No \u2014 el nombre viene de una flor','S\xed \u2014 por el polen en la atm\xf3sfera','S\xed \u2014 en los a\xf1os de eclipse','No \u2014 el nombre viene de una cantante'],explicacao:'La flor es la Phlox subulata, el musgo rosa que tapiza el suelo al comienzo de la primavera del este de Am\xe9rica del Norte. La Luna sigue del color de siempre \u2014 el nombre describe el calendario de flores de all\xe1, no el cielo de ac\xe1.',fonte:'Lista est\xe1ndar del Old Farmer\'s Almanac, siglo XX'},'lua-azul':{pergunta:'"Luna Azul es la segunda luna llena del mes." Esa definici\xf3n naci\xf3 como...',opcoes:['Folclore ingl\xe9s medieval','Un error de lectura en una revista, en 1946','C\xe1lculo oficial de los observatorios','Tradici\xf3n de los navegantes portugueses'],explicacao:'James Hugh Pruett ley\xf3 mal un art\xedculo del Maine Farmers\' Almanac \u2014 que usaba "Blue Moon" para la tercera llena de una estaci\xf3n con cuatro \u2014 y public\xf3 la versi\xf3n "segunda del mes" en Sky & Telescope en 1946. La NPR lo repiti\xf3 en 1980, el Trivial Pursuit lo cristaliz\xf3 en 1986, y la propia revista se corrigi\xf3 en 1999. Ninguna de las dos definiciones es antigua.',fonte:'Olson, Fienberg & Sinnott, "What\'s a Blue Moon?", Sky & Telescope, mayo/1999'},'lua-oito-fases':{pergunta:'\xbfDe qu\xe9 \xe9poca son las ocho fases de la Luna con lectura de personalidad?',opcoes:['De Babilonia','De Roma','De 1967 \u2014 Dane Rudhyar','De la Grecia de Hes\xedodo'],explicacao:'La divisi\xf3n antigua que tiene fuente es en cuatro cuartos, con cualidades de clima \u2014 h\xfamedo, caliente, seco, fr\xedo \u2014, en Ptolomeo. Las ocho fases nombradas con lectura psicol\xf3gica son de Dane Rudhyar: formuladas en The Lunation Cycle (1967), sobre una idea que ven\xeda desarrollando desde los a\xf1os 1930-40. Y "gibosa" es solo lat\xedn para "jorobada": describe la forma, no carga doctrina.',fonte:'Ptolomeo, Tetrabiblos I.8, siglo II \xb7 Dane Rudhyar, The Lunation Cycle, 1967'},'lua-minguante':{pergunta:'\xbfQu\xe9 reservaba el campo romano para la Luna menguante?',opcoes:['Sembrar todo','Casarse y bautizar','Nada \u2014 era fase de descanso','Cortar, cosechar y esquilar'],explicacao:'Todo lo que se corta, se cosecha y se esquila sufre menos da\xf1o con la luna menguante \u2014 as\xed resume Plinio la regla, y Cat\xf3n y Columela mandan a menguante tambi\xe9n el desmalezado, el esti\xe9rcol y el corte de madera. Lo que deb\xeda secar o disminuir iba todo a esa fase: es la regla lunar con m\xe1s fuente primaria que existe.',fonte:'Plinio el Viejo, Naturalis Historia XVIII.321-322, siglo I \xb7 Cat\xf3n, De Agri Cultura 29 y 31.2, siglo II a.C.'},'lua-catao-plantio':{pergunta:'Cat\xf3n, en el siglo II a.C., \xbfen qu\xe9 momento de la Luna mandaba plantar higuera y vid?',opcoes:['En la llena, a medianoche','En la "luna callada" (oscura), por la tarde','En el cuarto creciente, al amanecer','En cualquier d\xeda par'],explicacao:'"Luna silente" \u2014 la luna callada, cuando desaparece del cielo. Es el registro agr\xedcola romano de la idea de empezar en lo oscuro: la semilla va a la tierra cuando la Luna todav\xeda no aparece, y crece junto con ella. Dos mil a\xf1os despu\xe9s eso se volvi\xf3 "ritual de Luna Nueva" \u2014 la ra\xedz es una instrucci\xf3n de campo.',fonte:'Cat\xf3n el Viejo, De Agri Cultura 40.1, siglo II a.C.'},'lua-sangue':{pergunta:'\xbfDesde cu\xe1ndo existe "Luna de Sangre" como nombre de eclipse?',opcoes:['Desde la Biblia','Desde la Roma antigua','Desde 2008','Desde la Edad Media'],explicacao:'La imagen es b\xedblica \u2014 "la luna se convertir\xe1 en sangre", en el libro de Joel \u2014, pero el t\xe9rmino como nombre de evento es del pastor Mark Biltz, en 2008, y se volvi\xf3 mundial con el libro Four Blood Moons, de John Hagee. Los astr\xf3nomos no lo usan. Y la profec\xeda de la t\xe9trada de 2014-15 no se cumpli\xf3.',fonte:'Joel 2:31 (la imagen) \xb7 Mark Biltz, 2008, y John Hagee, Four Blood Moons, 2013 (el t\xe9rmino)'},'lua-intencoes':{pergunta:'"Escribir intenciones en la Luna Nueva", como se practica hoy, lo populariz\xf3...',opcoes:['Jan Spiller, en un libro de 2001','Cleopatra','Los monjes copistas','Nostradamus'],explicacao:'Plantar de verdad en la luna oscura es fuente primaria romana \u2014 Cat\xf3n y Paladio lo mandan. Cambiar la semilla por una intenci\xf3n escrita es transposici\xf3n reciente, popularizada por Jan Spiller en New Moon Astrology. El gesto de empezar en lo oscuro es viejo; la lista de deseos es de anteayer.',fonte:'Cat\xf3n, De Agri Cultura 40.1, siglo II a.C. (la siembra) \xb7 Jan Spiller, New Moon Astrology, 2001 (la intenci\xf3n)'},'lua-eclipse-pais':{pergunta:'Para Ptolomeo, en el siglo II, \xbfa qui\xe9n le concern\xeda un eclipse?',opcoes:['A quien naci\xf3 ese d\xeda','A pa\xedses, ciudades y reyes','A cada persona, seg\xfan su signo','A nadie \u2014 \xe9l no escribi\xf3 sobre eclipses'],explicacao:'En la fuente, el eclipse es asunto de mapamundi: Ptolomeo dedica seis cap\xedtulos del Tetrabiblos a prever efectos sobre regiones y gobernantes \u2014 hasta la duraci\xf3n la calcula por hora de oscuridad. "Tu temporada de eclipses te va a cambiar la vida" no viene de ah\xed: la aplicaci\xf3n individual es moderna.',fonte:'Ptolomeo, Tetrabiblos II.4-II.9, siglo II'},'lua-tempo-signo':{pergunta:'\xbfCu\xe1nto tiempo pasa la Luna en cada signo?',opcoes:['Exactamente 2 d\xedas y medio','Una semana','En promedio ~2,28 d\xedas \u2014 y var\xeda','Un mes'],explicacao:'El famoso "2 d\xedas y medio" es un redondeo: el promedio real es ~2,28 d\xedas (2d 6h40m), y var\xeda de ~1,95 a ~2,55 seg\xfan la velocidad de la Luna, que cambia a lo largo del mes. Parece detalle \u2014 pero es la diferencia entre tabla memorizada y cielo calculado, que es la pelea n\xfamero uno de esta app.',fonte:'Medici\xf3n astron\xf3mica: mes sideral de 27,32 d\xedas dividido por los 12 signos'},'lua-colheita-hemisferio':{pergunta:'La "Luna de la Cosecha" (Harvest Moon) de septiembre, \xbfvale al sur del ecuador?',opcoes:['Vale \u2014 el nombre es universal','Vale, pero solo en el extremo sur del continente','No \u2014 al sur del ecuador el fen\xf3meno no existe','No \u2014 ah\xed el equivalente cae en marzo'],explicacao:'El fen\xf3meno es real: cerca del equinoccio de oto\xf1o, la Luna llena sale casi a la misma hora varias noches seguidas. Solo que el oto\xf1o del hemisferio sur empieza en marzo \u2014 septiembre como "mes de la cosecha" es calendario del noreste de Estados Unidos; al sur del ecuador es primavera.',fonte:'Fen\xf3meno astron\xf3mico medible \xb7 nombre ingl\xe9s atestiguado desde 1706 (Merriam-Webster)'},'lua-saros':{pergunta:'"Saros", el nombre del ciclo de los eclipses, \xbfde d\xf3nde sali\xf3?',opcoes:['Es la palabra babil\xf3nica para "eclipse"','De un error de Halley en 1691 \u2014 se\xf1alado en 1756 y nunca corregido','Del griego, "sombra"','De un astr\xf3nomo persa'],explicacao:'Halley pesc\xf3 la palabra en un l\xe9xico bizantino y la peg\xf3 al ciclo de 18 a\xf1os \u2014 pero \u0161\u0101r, en babil\xf3nico, es el n\xfamero 3.600, no un ciclo de eclipses. Le Gentil se\xf1al\xf3 el error en 1756 y el nombre qued\xf3 as\xed igual. Los babilonios, due\xf1os del descubrimiento, lo llamaban "ciclo de 18 a\xf1os".',fonte:'Edmond Halley, 1691; el error se\xf1alado por Guillaume Le Gentil, 1756'},'hist-horoscopo-jornal':{pergunta:'El hor\xf3scopo de diario \u2014 doce casillas, una por signo \u2014 \xbfcu\xe1ndo se invent\xf3?',opcoes:['En Babilonia','En la Grecia cl\xe1sica','El 24 de agosto de 1930','En los a\xf1os 1960, en EE. UU.'],explicacao:'Fue por un nacimiento real: el Sunday Express le encarg\xf3 a R. H. Naylor un hor\xf3scopo de la princesa Margarita, reci\xe9n nacida \u2014 y el diario tuvo que explicarles a los lectores qu\xe9 era un hor\xf3scopo, porque en 1930 nadie lo sab\xeda. Las doce casillas nacieron de un problema editorial: el \xfanico dato que todo lector sabe de memoria es su propia fecha de nacimiento.',fonte:'R. H. Naylor, "What the Stars Foretell for the New Princess", Sunday Express, 24/08/1930'},'hist-horoscopo-antigo':{pergunta:'\xbfDe qu\xe9 a\xf1o es el hor\xf3scopo individual m\xe1s antiguo que se conoce?',opcoes:['3000 a.C.','410 a.C.','150 d.C.','1781'],explicacao:'Es una tablilla de arcilla babil\xf3nica con el cielo de la noche de un nacimiento \u2014 y es solo una lista de posiciones: sin Ascendente, sin casas, sin ninguna interpretaci\xf3n. La carta natal como sistema de lectura es invenci\xf3n griega, unos tres siglos despu\xe9s, en Alejandr\xeda.',fonte:'Francesca Rochberg, Babylonian Horoscopes, American Philosophical Society, 1998'},'hist-babilonios':{pergunta:'\xbfQu\xe9 le\xedan en el cielo los sacerdotes de Babilonia?',opcoes:['Presagios de Estado \u2014 rey, guerra, cosecha','La carta natal de cada persona','La pareja ideal de cada signo','El nombre que deb\xeda recibir cada ni\xf1o'],explicacao:'La serie En\u016bma Anu Enlil tiene miles de presagios, y todos le hablan al palacio: "si tal fen\xf3meno, entonces tal consecuencia para el rey y para el pa\xeds". La astrolog\xeda m\xe1s antigua no era sobre ti \u2014 el registro individual solo aparece siglos despu\xe9s, y la interpretaci\xf3n individual es griega.',fonte:'En\u016bma Anu Enlil, serie cuneiforme, compilaci\xf3n c. siglos XVI-XII a.C.'},'hist-nechepso':{pergunta:'Los textos que fundaron la carta natal circulaban firmados por "Nechepso y Petosiris". \xbfQui\xe9nes eran?',opcoes:['Un fara\xf3n y un sacerdote de verdad','Dos astr\xf3nomos de la corte persa','Disc\xedpulos directos de Ptolomeo','Seud\xf3nimos \u2014 autores griegos fingiendo antig\xfcedad egipcia'],explicacao:'Autores griegos de Alejandr\xeda, alrededor de 150-120 a.C., firmaron como un fara\xf3n y un sacerdote para darle pedigr\xed egipcio a lo que estaban escribiendo en ese momento. La astrolog\xeda occidental empieza con una falsificaci\xf3n de antig\xfcedad \u2014 el mismo gesto que Court de G\xe9belin repetir\xeda con el tarot, 1.900 a\xf1os despu\xe9s.',fonte:'Corpus de Nechepso-Petosiris, c. 150-120 a.C.; fragmentos recogidos por Riess, 1892'},'hist-tendencias':{pergunta:'La frase "la astrolog\xeda no predice, apunta tendencias" \xbfd\xf3nde naci\xf3?',opcoes:['En los templos de Babilonia','En un tribunal de Londres, como defensa penal','En un congreso de astr\xf3nomos','En la contracultura de los a\xf1os 1960'],explicacao:'Alan Leo, el hombre que industrializ\xf3 el hor\xf3scopo, fue procesado dos veces por adivinaci\xf3n bajo la ley inglesa; la defensa dec\xeda que \xe9l describ\xeda "tendencias", no fortunas. Se cay\xf3 cuando la acusaci\xf3n ley\xf3 en voz alta una predicci\xf3n de muerte del almanaque de \xe9l \u2014 condenado, multa de cinco libras. El mercado hered\xf3 la frase sin saber que naci\xf3 como tesis de defensa, en 1914-1917.',fonte:'Procesos de Alan Leo, Londres, 1914 y 1917'},'hist-contra-astrologos':{pergunta:'\xbfQui\xe9n escribi\xf3, todav\xeda en la Antig\xfcedad, un libro entero llamado "Contra los Astr\xf3logos"?',opcoes:['Nadie \u2014 la cr\xedtica es invenci\xf3n moderna','Julio C\xe9sar','Sexto Emp\xedrico, en el siglo III','El emperador Ner\xf3n'],explicacao:'El desacuerdo es tan antiguo como la pr\xe1ctica: Sexto Emp\xedrico escribi\xf3 el Contra los Astr\xf3logos en el siglo III, y \xe9l es fuente primaria tanto como Ptolomeo. "Conocimiento milenario" aplana cuatro mil a\xf1os de gente discutiendo \u2014 y la discusi\xf3n es la parte m\xe1s interesante de la historia.',fonte:'Sexto Emp\xedrico, Contra los Astr\xf3logos, siglo III'},'hist-mercurio-retro':{pergunta:'"Mercurio retr\xf3grado rompe celulares y tumba contratos." \xbfQu\xe9 dice de verdad la fuente antigua?',opcoes:['Habla de atraso: expectativas y emprendimientos postergados','Exactamente eso, pero con carretas','Manda viajar m\xe1s','Nada \u2014 nadie observaba la retrogradaci\xf3n'],explicacao:'La fuente habla de espera, no de aparatos: Vetio Valente escribe que los planetas retr\xf3grados "postergan expectativas, acciones, ganancias y emprendimientos" \u2014 y que la segunda estaci\xf3n "cancela el atraso". Nada de tecnolog\xeda ni de ex. La expresi\xf3n "Mercurio retr\xf3grado" ni siquiera aparece en la prensa general antes de 1996.',fonte:'Vetio Valente, Antolog\xedas, siglo II'},'hist-retro-frequencia':{pergunta:'\xbfUn planeta retr\xf3grado en el cielo es cosa rara?',opcoes:['Rar\xedsima \u2014 una vez por d\xe9cada','No \u2014 en el 85,9% de los d\xedas hay alg\xfan planeta retr\xf3grado','Solo pasa en a\xf1o bisiesto','Imposible \u2014 un planeta no anda para atr\xe1s'],explicacao:'Midiendo con la efem\xe9ride: Saturno pasa 36,3% del tiempo retr\xf3grado, Plut\xf3n 44,4% \u2014 y en el 85,9% de los d\xedas hay alg\xfan planeta retr\xf3grado en el cielo. Si la retrogradaci\xf3n pusiera la vida de cabeza, estar de cabeza ser\xeda lo normal. El movimiento es aparente: perspectiva de las \xf3rbitas, no marcha atr\xe1s.',fonte:'Medici\xf3n propia con efem\xe9ride astron\xf3mica \u2014 base de tradici\xf3n de la app, doc 11'},'hist-urano':{pergunta:'\xbfAcuario "siempre fue" regido por Urano?',opcoes:['S\xed \u2014 desde los caldeos','S\xed \u2014 est\xe1 en el Tetrabiblos','No \u2014 Urano solo se descubri\xf3 en 1781; en la tradici\xf3n, Acuario era de Saturno','No \u2014 Acuario era del Sol'],explicacao:'No puede un signo ser "desde siempre" de un planeta que nadie conoc\xeda: Urano entra en la carta en 1781, y la atribuci\xf3n a Acuario empieza alrededor de 1825-1828 \u2014 en 1834 un lector todav\xeda preguntaba por qu\xe9 el planeta nuevo no ten\xeda ninguna casa. En el Tetrabiblos, Acuario es domicilio de Saturno.',fonte:'Ptolomeo, Tetrabiblos I.17, siglo II \xb7 atribuci\xf3n a Urano: Smith, 1825 / Varley, 1828'},'hist-semana-planetaria':{pergunta:'Lunes de la Luna, martes de Marte... \xbfLa semana planetaria ya era "inmemorial" para los romanos?',opcoes:['No \u2014 quien la registra ya llamaba a la costumbre "comparativamente reciente"','S\xed \u2014 ven\xeda del inicio de los tiempos','S\xed \u2014 la decret\xf3 R\xf3mulo','No \u2014 se invent\xf3 en el siglo XIX'],explicacao:'Di\xf3n Casio, el historiador que documenta la costumbre, escribe que los griegos antiguos no la conoc\xedan y que la adopci\xf3n era reciente \u2014 y encima da dos explicaciones que compiten para el orden de los d\xedas, porque ni \xe9l estaba seguro. Hasta la fuente antigua ve\xeda la moda como nueva.',fonte:'Di\xf3n Casio, Historia Romana 37.18-19, siglo III'},'hist-porcentagem':{pergunta:'El "porcentaje de compatibilidad" entre signos, \xbfde qu\xe9 fuente antigua viene?',opcoes:['Del Tetrabiblos de Ptolomeo','Del Carmen Astrologicum de Doroteo','De los papiros de Alejandr\xeda','De ninguna \u2014 no existe n\xfamero en fuente antigua'],explicacao:'Revisados Ptolomeo, Doroteo, M\u0101sh\u0101\'all\u0101h y Lilly: ning\xfan n\xfamero, ning\xfan "87%". Lo que la tradici\xf3n tiene es una escala de cuatro escalones \u2014 y ah\xed la oposici\xf3n queda en el fondo, no en el tope que suelen darle las apps. El porcentaje es convenci\xf3n medi\xe1tica del siglo XX, sin inventor documentado.',fonte:'Ptolomeo, Tetrabiblos IV.7, siglo II (la escala ordinal); el porcentaje: siglo XX, sin autor identificado'},'hist-leao-coracao':{pergunta:'En la lista antigua que ligaba signos a partes del cuerpo, \xbfa qu\xe9 correspond\xeda Leo?',opcoes:['Al coraz\xf3n, claro','A los flancos y a los om\xf3platos','A la cabeza','A los pies'],explicacao:'"Leo = coraz\xf3n" no est\xe1 en Manilio ni en Ptolomeo: en Manilio, autor de la lista de los doce signos, Leo se quedaba con los flancos y los om\xf3platos \u2014 y Libra, que el mercado le da a los ri\xf1ones, se quedaba con las nalgas. La versi\xf3n "coraz\xf3n" es datable: aparece impresa en la Escala del Doce de Agrippa, en 1533.',fonte:'Manilio, Astronomica II.453-465, siglo I \xb7 Agrippa, Escala del Doce, 1533'},'hist-signo-solar':{pergunta:'En la astrolog\xeda antigua, el signo solar \u2014 "tu signo" \u2014 \xbfera el centro de todo?',opcoes:['No \u2014 el Sol era uno de los siete planetas; lo que marcaba al individuo era el Ascendente','S\xed \u2014 desde siempre','S\xed \u2014 Ptolomeo manda empezar por \xe9l','No \u2014 el centro era J\xfapiter'],explicacao:'En la tradici\xf3n, el significador del individuo es el Ascendente \u2014 y el car\xe1cter, en Ptolomeo, viene de Mercurio y de la Luna. El signo solar se volvi\xf3 el centro por dos motivos con nombre y fecha: Alan Leo, que necesitaba producir lecturas en escala, y el diario de 1930, que necesitaba doce casillas.',fonte:'Ptolomeo, Tetrabiblos III.13, siglo II \xb7 Alan Leo, 1895-1917 \xb7 Naylor, 1930'},'hist-cuspide':{pergunta:'Quien nace "en la c\xfaspide", \xbfes un poco de los dos signos?',opcoes:['S\xed \u2014 es doctrina antigua','S\xed \u2014 pero solo en las c\xfaspides de agua','No \u2014 la frontera de signo es un instante exacto; lo que se equivoca es la tabla de fechas','No \u2014 c\xfaspide es error de traducci\xf3n'],explicacao:'Los signos empiezan en los equinoccios y solsticios, que son instantes \u2014 Ptolomeo escribe que se cuentan a partir de ellos "y de ninguna otra fuente". Lo que crea la leyenda es la tabla de fecha fija de los almanaques, que se equivoca de verdad en las fronteras (29% de los d\xedas de cambio, medido). La respuesta no es "soy de los dos": es calcular la longitud del Sol a la hora del nacimiento \u2014 que es lo que hace esta app.',fonte:'Ptolomeo, Tetrabiblos I.22, siglo II \xb7 medici\xf3n propia de la app: 318 de 1.092 d\xedas de cambio errados por tabla'},'hist-5000-anos':{pergunta:'"La astrolog\xeda tiene 5.000 a\xf1os." \xbfCu\xe1l es la cuenta honesta?',opcoes:['5.000 justos, desde las pir\xe1mides','Unos 2.000 a 2.500 a\xf1os de tradici\xf3n textual continua','10.000, desde las cavernas','300 a\xf1os, desde los diarios'],explicacao:'Lo que tiene ~4.000 a\xf1os son presagios de Estado mesopot\xe1micos \u2014 otra cosa, sin carta individual. El zod\xedaco tiene ~2.450 a\xf1os, el hor\xf3scopo individual m\xe1s antiguo es de 410 a.C., y la carta natal con Ascendente tiene ~2.150. Dos milenios y pico de textos continuos ya es impresionante \u2014 no hace falta inflar.',fonte:'S\xedntesis de la investigaci\xf3n en fuente primaria de esta app \u2014 base de tradici\xf3n, doc 10 \xa714.1'}}}},1645,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"default",{enumerable:!0,get:function(){return t}});var t={tela:{titulo:'Did you know?',subtitulo:'Seven questions a day \u2014 the myth falls, the source stays',contador:(t,o)=>`Question ${t} of ${o}`,certo:'Right on the source!',errado:'Not this time \u2014 the right one is marked.',fontePrefixo:'Source: ',proxima:'Next question',verPlacar:'See your score',placarTitulo:'Today\'s round',placarDe:(t,o)=>`${t} of ${o}`,acumulado:(t,o)=>`In total you've answered ${t} question${1===t?'':'s'} \u2014 ${o} on the right source.`,amanha:'Tomorrow brings seven new ones. The round changes with the day \u2014 and it\'s the same for everyone, so you can compare.',rodadaFeitaAviso:'You already played today\'s round.',a11yOpcao:t=>`Option ${t}`},temas:{taro:'Tarot',lua:'Moon',historia:'History'},placar:['Clean round: seven out of seven on the right source. Those are exactly the stories that circulate wrong out there \u2014 and you just checked every one of them against the receipt.','Almost all of it on the right source. The ones that got away came with the explanation and the receipt right above \u2014 and tomorrow there are seven more.','Half and half \u2014 and that adds up: a good part of these stories has been circulating wrong for decades, with a date and an author for the mistake. Now you know where to check.','The "obvious" answers in this quiz are exactly the ones the market repeats with no source. Every explanation above tells the real story, with an author and a date \u2014 and tomorrow there\'s a rematch.'],perguntas:{'taro-leitura-nascimento':{pergunta:'When was tarot born as a way to read the future?',opcoes:['In ancient Egypt, with the Book of Thoth','In 15th-century Italy, along with the cards','In the 18th century \u2014 before that, tarot was just a card game','In classical Greece, in the oracle temples'],explicacao:'The deck has been around since 15th-century Italy \u2014 but it spent some 350 years as a gambling and parlor game, and it\'s still played today in France and Austria. The oldest documented reading is a Bolognese sheet from before 1750, and the first published method is Etteilla\'s, in 1783. Honest summary: six centuries of imagery, two and a half centuries of reading.',fonte:'Bolognese sheet (before 1750), found by Franco Pratesi \xb7 Etteilla, first published method, 1783'},'taro-egito-autor':{pergunta:'Who invented the story that tarot comes from Egypt?',opcoes:['Egyptian priests, in temple papyri','Antoine Court de G\xe9belin, in a book from 1781','The first Italian card makers','Aleister Crowley, in 1944'],explicacao:'Court de G\xe9belin saw a game of tarot at a Paris social gathering, thought he recognized Egyptian symbols and published that it was the Book of Thoth \u2014 without producing a single document. The detail that brings it all down: he wrote that in 1781, and nobody in the world could read Egyptian before Champollion cracked the hieroglyphs, in 1822.',fonte:'Antoine Court de G\xe9belin, Le Monde primitif, vol. 8, "Du Jeu des Tarots", 1781'},'taro-waite-refuta':{pergunta:'What did Waite \u2014 author of the best-selling deck in the world \u2014 write in 1911 about tarot\'s Egyptian origin?',opcoes:['That there isn\'t "a particle of evidence" for it','That it was the deck\'s greatest secret','That only initiates could confirm it','That the pharaohs left it carved in the temples'],explicacao:'Waite gives a whole section of the Pictorial Key to taking Court de G\xe9belin apart: he calls his ten arguments "pillars of sand" and points out that the Egyptian etymology was proposed when nobody could read Egyptian. Saying tarot doesn\'t come from Egypt puts you on the side of the deck\'s own author \u2014 not against him.',fonte:'A. E. Waite, The Pictorial Key to the Tarot, Part I \xa74, 1911'},'taro-quem-desenhou':{pergunta:'Who drew the 78 cards of the famous "Waite deck", released in December 1909?',opcoes:['A. E. Waite himself','\xc9liphas L\xe9vi','An anonymous London print shop','The artist Pamela Colman Smith'],explicacao:'Waite commissioned and directed it, but the one who drew card by card was Pamela Colman Smith \u2014 which is why the fair name is Rider-Waite-Smith. For the 56 minor cards, Smith leaned on the Sola Busca, an Italian deck from around 1491 whose photographs had just landed at the British Museum, in 1907.',fonte:'Waite-Smith deck, Dec/1909 \xb7 A. E. Waite, The Pictorial Key to the Tarot, 1911'},'taro-estrela':{pergunta:'In Waite\'s list of meanings (1911), the Star card means, first of all...',opcoes:['Hope and a bright future','A long voyage by sea','Loss, theft, privation, abandonment','A reunion with an old love'],explicacao:'It\'s the most jarring entry on the list: Waite writes "Loss, theft, privation, abandonment" \u2014 and only then notes that "another reading says: hope and bright prospects". Modern reading flipped the priority by following Smith\'s picture, not Waite\'s text: the two halves of the deck never told the same story.',fonte:'A. E. Waite, The Pictorial Key to the Tarot, 1911 \u2014 card XVII, The Star'},'taro-morte':{pergunta:'And the Death card, on that same Waite list (1911), means...',opcoes:['It never means death, only a fresh start','"End, mortality, destruction"','An unexpected inheritance','A wedding coming up'],explicacao:'The "transformation" reading is an ethical choice of the twentieth century \u2014 a legitimate one, and the one this app uses \u2014 but it wasn\'t there at the start: Waite writes "End, mortality, destruction, corruption". Knowing what the author wrote and what practice chose later is half the battle when it comes to reading tarot without repeating legends.',fonte:'A. E. Waite, The Pictorial Key to the Tarot, 1911 \u2014 card XIII'},'taro-cruz-celta':{pergunta:'Is the "Celtic Cross" spread actually Celtic?',opcoes:['Yes \u2014 it comes from the druids of Ireland','Yes \u2014 it shows up in medieval manuscripts','No \u2014 it\'s Egyptian, despite the name','No \u2014 the name is Waite\'s, from 1911'],explicacao:'The name shows up for the first time in Waite\'s book, which only says the method "has been long used in private". The structure comes out of the Golden Dawn circles of the 1890s \u2014 no Celtic attestation, no druid anywhere in the process.',fonte:'A. E. Waite, The Pictorial Key to the Tarot, Part III \xa77, 1911'},'taro-tres-cartas':{pergunta:'Where does the three-card Past / Present / Future spread come from?',opcoes:['Nobody has found a primary source \u2014 it caught on in the twentieth century','From Waite\'s Pictorial Key','From the Golden Dawn','From the temples of Egypt'],explicacao:'Waite gives three methods in the book \u2014 of 10, 42 and 35 cards \u2014 and none of them is a three-card timeline; the Golden Dawn used a different spread, the Opening of the Key, an operation that takes hours. The three-card spread is legitimate as practice \u2014 you just can\'t call it "the classic one", because nobody has found the text that founds it.',fonte:'Checked in A. E. Waite, The Pictorial Key to the Tarot, 1911 \u2014 the spread is not there'},'taro-invertidas':{pergunta:'Who was the first to publish reversed-card meanings, one for every card?',opcoes:['The Marseille card makers','Waite, in 1911','Etteilla, starting in 1770','A thousand-year-old oral tradition, with no written record'],explicacao:'Etteilla set up systematic reversed meanings \u2014 every reversed reading in the world descends from him. And there\'s a surprise in Waite: there, the reversal is usually a sideways sense, sometimes better than the upright one \u2014 the Wheel of Fortune upside down becomes "increase, abundance".',fonte:'Etteilla, first cartomancy manual with reversals, 1770 \xb7 Waite, 1911'},'taro-78-cartas':{pergunta:'Does every tarot deck have 78 cards?',opcoes:['Yes \u2014 the number was fixed from the start','No \u2014 the Minchiate of Florence has 97; the Bolognese, 62','Yes \u2014 78 is the sum of the Hebrew letters','No \u2014 the number changes every century'],explicacao:'The 78 is the pattern that won, not a law: the Florentine Minchiate has 97 cards, the Tarocco Bolognese has 62 and the Sicilian one, 64. It also takes down the numerology of "22 cards = 22 Hebrew letters" \u2014 historical patterns don\'t always have 22 trumps.',fonte:'Historical Italian patterns (Minchiate, Bolognese, Siciliano) \u2014 Dummett, The Game of Tarot, 1980'},'taro-marselha':{pergunta:'Is the "Tarot de Marseille" the oldest tarot there is?',opcoes:['No \u2014 the oldest ones are Italian, hand-painted in the fifteenth century','Yes \u2014 it was designed in Marseille in the twelfth century','Yes \u2014 it arrived on Phoenician ships','No \u2014 it\'s a copy of the Waite deck'],explicacao:'The oldest surviving tarots are the hand-painted Italian ones, like the Visconti-Sforza decks from the middle of the fifteenth century. The "Marseille" pattern is later French printing (Noblet c. 1650, Conver 1760) \u2014 and the trade name "Ancien Tarot de Marseille" was made popular by Paul Marteau, of the Grimaud house, in 1930.',fonte:'Paul Marteau / Grimaud, Ancien Tarot de Marseille, 1930'},'lua-superlua':{pergunta:'Who coined the word "Supermoon"?',opcoes:['NASA, in the Apollo era','Galileo, when he pointed his telescope up','The colonial American almanacs','The astrologer Richard Nolle, in a magazine in 1979'],explicacao:'"Supermoon" sounds like an observatory term, but it was born in a horoscope magazine: Richard Nolle coined the name in Dell Horoscope in 1979, and the press only picked it up in bulk in 2011. The technical name is perigee syzygy \u2014 and the size difference, real as it is (~14%), goes unnoticed by the naked eye without a side-by-side photo.',fonte:'Richard Nolle, Dell Horoscope magazine, 1979'},'lua-cheia-lavoura':{pergunta:'In Roman farming, the Full Moon was the time for what?',opcoes:['Harvesting everything that was ripe','Sowing broad beans','Cutting timber','Shearing the sheep'],explicacao:'It\'s the opposite of what gets repeated everywhere: harvesting, cutting and shearing were waning-moon work \u2014 Pliny notes that this way the plant "suffers less damage". At the full moon, Columella called for sowing beans. The farm rule went: waxing to put in, waning to take out \u2014 and beans on the eve of the full moon was Columella\'s specific instruction.',fonte:'Columella, De Re Rustica XI.2.85, 1st c. \xb7 Pliny the Elder, Naturalis Historia XVIII.321, 1st c.'},'lua-nomes-almanaque':{pergunta:'"Wolf Moon", "Strawberry Moon", "Snow Moon" \u2014 where do those names come from?',opcoes:['From the Indigenous peoples of the Amazon','From Greek mythology','From U.S. farm almanacs, in the 1930s','From the Celtic druids'],explicacao:'The standard list came out of an American farm almanac: the Maine Farmers\' Almanac published the names in the 1930s, and the Old Farmer\'s Almanac trimmed it to one name per month. It\'s a mix of Algonquian, English and Celtic sources sold as a single system \u2014 and it describes the farming year of the U.S. Northeast: below the equator, "Snow Moon" in February lands in the middle of summer.',fonte:'Maine Farmers\' Almanac, 1930s \xb7 first printed list: Daniel Carter Beard, 1918'},'lua-rosa':{pergunta:'In April, does the "Pink Moon" actually turn pink?',opcoes:['No \u2014 the name comes from a flower','Yes \u2014 because of pollen in the atmosphere','Yes \u2014 in eclipse years','No \u2014 the name comes from a singer'],explicacao:'The flower is Phlox subulata, the moss pink that carpets the ground in early spring in eastern North America. The Moon stays the color it always is \u2014 the name describes the flower calendar of that one region, not the sky above you.',fonte:'Standard list of the Old Farmer\'s Almanac, 20th c.'},'lua-azul':{pergunta:'"A Blue Moon is the second full moon in a month." That definition was born as...',opcoes:['Medieval English folklore','A misreading in a magazine, in 1946','The official calculation of the observatories','A tradition of Portuguese navigators'],explicacao:'James Hugh Pruett misread an article in the Maine Farmers\' Almanac \u2014 which used "Blue Moon" for the third full moon in a season with four \u2014 and published the "second in the month" version in Sky & Telescope in 1946. NPR repeated it in 1980, Trivial Pursuit set it in stone in 1986, and the magazine itself ran the correction in 1999. Neither definition is old.',fonte:'Olson, Fienberg & Sinnott, "What\'s a Blue Moon?", Sky & Telescope, May/1999'},'lua-oito-fases':{pergunta:'The eight moon phases with personality readings date from when?',opcoes:['From Babylon','From Rome','From 1967 \u2014 Dane Rudhyar','From the Greece of Hesiod'],explicacao:'The old division that has a source behind it is into four quarters, with weather qualities \u2014 moist, hot, dry, cold \u2014 in Ptolemy. The eight named phases with psychological readings are Dane Rudhyar\'s: set out in The Lunation Cycle (1967), on an idea he\'d been developing since the 1930-40s. And "gibbous" is just Latin for "humpbacked": it describes the shape, it carries no doctrine.',fonte:'Ptolemy, Tetrabiblos I.8, 2nd c. \xb7 Dane Rudhyar, The Lunation Cycle, 1967'},'lua-minguante':{pergunta:'What did Roman farming save for the waning Moon?',opcoes:['Sowing everything','Weddings and baptisms','Nothing \u2014 it was the resting phase','Cutting, harvesting and shearing'],explicacao:'Everything you cut, harvest or shear takes less damage under a waning moon \u2014 that\'s how Pliny sums up the rule, and Cato and Columella send weeding, manuring and timber cutting to the waning moon as well. Whatever was supposed to dry out or shrink went to that phase: it\'s the lunar rule with the most primary sources behind it.',fonte:'Pliny the Elder, Naturalis Historia XVIII.321-322, 1st c. \xb7 Cato, De Agri Cultura 29 and 31.2, 2nd c. BC'},'lua-catao-plantio':{pergunta:'Cato, in the second century BC, said to plant fig and grapevine at which moment of the Moon?',opcoes:['At the full moon, at midnight','At the "silent moon" (dark), in the afternoon','At the first quarter, at dawn','On any even-numbered day'],explicacao:'"Luna silente" \u2014 the silent moon, when it disappears from the sky. It\'s the Roman farming record of the idea of starting in the dark: the seed goes into the ground while the Moon is still out of sight, and grows along with it. Two thousand years later that turned into a "New Moon ritual" \u2014 the root is a farm instruction.',fonte:'Cato the Elder, De Agri Cultura 40.1, 2nd c. BC'},'lua-sangue':{pergunta:'How long has "Blood Moon" been a name for an eclipse?',opcoes:['Since the Bible','Since ancient Rome','Since 2008','Since the Middle Ages'],explicacao:'The image is biblical \u2014 "the moon shall be turned into blood", in the book of Joel \u2014 but the term as the name of an event comes from pastor Mark Biltz, in 2008, and went global with John Hagee\'s book Four Blood Moons. Astronomers don\'t use it. And the prophecy about the 2014-15 tetrad didn\'t come true.',fonte:'Joel 2:31 (the image) \xb7 Mark Biltz, 2008, and John Hagee, Four Blood Moons, 2013 (the term)'},'lua-intencoes':{pergunta:'"Writing intentions at the New Moon", the way it\'s done today, was popularized by...',opcoes:['Jan Spiller, in a book from 2001','Cleopatra','The copyist monks','Nostradamus'],explicacao:'Actually planting at the dark moon is Roman primary source \u2014 Cato and Palladius call for it. Swapping the seed for a written intention is a recent transposition, made popular by Jan Spiller in New Moon Astrology. The gesture of starting in the dark is old; the wish list is from the day before yesterday.',fonte:'Cato, De Agri Cultura 40.1, 2nd c. BC (the planting) \xb7 Jan Spiller, New Moon Astrology, 2001 (the intention)'},'lua-eclipse-pais':{pergunta:'For Ptolemy, in the second century, an eclipse was about whom?',opcoes:['Whoever was born that day','Countries, cities and kings','Each person, according to their sign','Nobody \u2014 he never wrote about eclipses'],explicacao:'In the source, an eclipse is a world-map matter: Ptolemy gives six chapters of the Tetrabiblos to predicting effects on regions and rulers \u2014 he even works out how long they last by the hours of darkness. "Your eclipse season is going to flip your life" doesn\'t come from there: applying it to one person is modern.',fonte:'Ptolemy, Tetrabiblos II.4-II.9, 2nd c.'},'lua-tempo-signo':{pergunta:'How long does the Moon stay in each sign?',opcoes:['Exactly 2 and a half days','A week','On average ~2.28 days \u2014 and it varies','A month'],explicacao:'The famous "2 and a half days" is a rounding: the real average is ~2.28 days (2d 6h40m), ranging from ~1.95 to ~2.55 depending on the Moon\'s speed, which changes over the month. It sounds like a detail \u2014 but it\'s the difference between a memorized table and a calculated sky, which is this app\'s number one fight.',fonte:'Astronomical measurement: a sidereal month of 27.32 days divided by the 12 signs'},'lua-colheita-hemisferio':{pergunta:'Does September\'s "Harvest Moon" work everywhere on Earth?',opcoes:['It does \u2014 the name is universal','It does, but only in the northern half of the country','No \u2014 below the equator the phenomenon doesn\'t exist','No \u2014 south of the equator the equivalent falls in March'],explicacao:'The phenomenon is real: near the autumn equinox, the full Moon rises at nearly the same time for several nights in a row. It just happens that autumn south of the equator starts in March \u2014 September as "harvest month" is the calendar of the U.S. Northeast; below the equator it\'s spring.',fonte:'Measurable astronomical phenomenon \xb7 English name attested since 1706 (Merriam-Webster)'},'lua-saros':{pergunta:'Where did "Saros", the name of the eclipse cycle, come from?',opcoes:['It\'s the Babylonian word for "eclipse"','From a mistake by Halley in 1691 \u2014 pointed out in 1756 and never fixed','From the Greek for "shadow"','From a Persian astronomer'],explicacao:'Halley fished the word out of a Byzantine lexicon and stuck it on the 18-year cycle \u2014 but \u0161\u0101r, in Babylonian, is the number 3,600, not an eclipse cycle. Le Gentil pointed out the mistake in 1756 and the name stayed anyway. The Babylonians, who owned the discovery, called it the "18-year cycle".',fonte:'Edmond Halley, 1691; the mistake pointed out by Guillaume Le Gentil, 1756'},'hist-horoscopo-jornal':{pergunta:'The newspaper horoscope \u2014 twelve boxes, one per sign \u2014 was invented when?',opcoes:['In Babylon','In classical Greece','On August 24, 1930','In the 1960s, in the U.S.'],explicacao:'It came out of a royal birth: the Sunday Express commissioned R. H. Naylor to do a horoscope for the newborn Princess Margaret \u2014 and the paper had to explain to its readers what a horoscope even was, because in 1930 nobody knew. The twelve boxes were born of an editorial problem: the one piece of data every reader knows by heart is their own birth date.',fonte:'R. H. Naylor, "What the Stars Foretell for the New Princess", Sunday Express, 24/08/1930'},'hist-horoscopo-antigo':{pergunta:'The oldest known individual horoscope is from what year?',opcoes:['3000 BC','410 BC','AD 150','1781'],explicacao:'It\'s a Babylonian clay tablet with the sky on the night of a birth \u2014 and it\'s only a list of positions: no Ascendant, no houses, no interpretation at all. The birth chart as a system of reading is a Greek invention, some three centuries later, in Alexandria.',fonte:'Francesca Rochberg, Babylonian Horoscopes, American Philosophical Society, 1998'},'hist-babilonios':{pergunta:'What did the priests of Babylon read in the sky?',opcoes:['Omens of state \u2014 king, war, harvest','Each person\'s birth chart','The ideal match for each sign','The name each child should be given'],explicacao:'The En\u016bma Anu Enlil series holds thousands of omens, and every one of them speaks to the palace: "if such a phenomenon, then such a consequence for the king and for the country". The oldest astrology wasn\'t about you \u2014 the individual record only shows up centuries later, and individual interpretation is Greek.',fonte:'En\u016bma Anu Enlil, cuneiform series, compiled c. XVI-XII centuries BC'},'hist-nechepso':{pergunta:'The texts that founded the birth chart circulated signed by "Nechepso and Petosiris". Who were they?',opcoes:['A real pharaoh and a real priest','Two astronomers of the Persian court','Direct disciples of Ptolemy','Pen names \u2014 Greek authors faking Egyptian antiquity'],explicacao:'Greek authors in Alexandria, around 150-120 BC, signed as a pharaoh and a priest to lend Egyptian pedigree to what they were writing right then. Western astrology begins with a forged antiquity \u2014 the same move Court de G\xe9belin would repeat with tarot, 1,900 years later.',fonte:'Nechepso-Petosiris corpus, c. 150-120 BC; fragments collected by Riess, 1892'},'hist-tendencias':{pergunta:'Where was the line "astrology doesn\'t predict, it points to tendencies" born?',opcoes:['In the temples of Babylon','In a London courtroom, as a criminal defense','At an astronomers\' conference','In the counterculture of the 1960s'],explicacao:'Alan Leo, the man who industrialized the horoscope, was prosecuted twice for fortune-telling under English law; his defense was that he described "tendencies", not fortunes. It collapsed when the prosecution read out loud a death prediction from his own almanac \u2014 convicted, fined five pounds. The market inherited the line without knowing it was born as a defense argument, in 1914-1917.',fonte:'Alan Leo trials, London, 1914 and 1917'},'hist-contra-astrologos':{pergunta:'Who wrote, back in antiquity, an entire book called "Against the Astrologers"?',opcoes:['Nobody \u2014 the criticism is a modern invention','Julius Caesar','Sextus Empiricus, in the third century','The emperor Nero'],explicacao:'The disagreement is as old as the practice: Sextus Empiricus wrote Against the Astrologers in the third century, and he\'s a primary source every bit as much as Ptolemy. "Ancient wisdom" flattens four thousand years of people arguing \u2014 and the argument is the most interesting part of the story.',fonte:'Sextus Empiricus, Against the Astrologers, 3rd c.'},'hist-mercurio-retro':{pergunta:'"Mercury retrograde breaks your phone and kills deals." What does the ancient source actually say?',opcoes:['It talks about delay: expectations and ventures postponed','Exactly that, only with carts','It says to travel more','Nothing \u2014 nobody tracked retrogrades'],explicacao:'The source talks about waiting, not about devices: Vettius Valens writes that retrograde planets "postpone expectations, actions, profits and undertakings" \u2014 and that the second station "cancels the delay". Nothing about tech, nothing about your ex. The phrase "Mercury retrograde" doesn\'t even show up in the general press before 1996.',fonte:'Vettius Valens, Anthologies, 2nd c.'},'hist-retro-frequencia':{pergunta:'Is a retrograde planet in the sky a rare thing?',opcoes:['Extremely rare \u2014 once a decade','No \u2014 on 85.9% of days some planet is retrograde','It only happens in leap years','Impossible \u2014 planets don\'t move backwards'],explicacao:'Measured against the ephemeris: Saturn spends 36.3% of the time retrograde, Pluto 44.4% \u2014 and on 85.9% of days some planet is retrograde in the sky. If retrogrades turned life upside down, upside down would be the normal state. The motion is apparent: a matter of orbital perspective, not reverse gear.',fonte:'Our own measurement with an astronomical ephemeris \u2014 the app\'s tradition base, doc 11'},'hist-urano':{pergunta:'Has Aquarius "always" been ruled by Uranus?',opcoes:['Yes \u2014 since the Chaldeans','Yes \u2014 it\'s in the Tetrabiblos','No \u2014 Uranus was only discovered in 1781; in the tradition, Aquarius belonged to Saturn','No \u2014 Aquarius belonged to the Sun'],explicacao:'A sign can\'t have "always" belonged to a planet nobody knew about: Uranus enters the chart in 1781, and the attribution to Aquarius starts around 1825-1828 \u2014 in 1834 a reader was still asking why the new planet had no house at all. In the Tetrabiblos, Aquarius is Saturn\'s domicile.',fonte:'Ptolemy, Tetrabiblos I.17, 2nd c. \xb7 attribution to Uranus: Smith, 1825 / Varley, 1828'},'hist-semana-planetaria':{pergunta:'Monday for the Moon, Saturday for Saturn... was the planetary week already "immemorial" to the Romans?',opcoes:['No \u2014 the man who records it already called the custom "comparatively recent"','Yes \u2014 it went back to the beginning of time','Yes \u2014 Romulus decreed it','No \u2014 it was invented in the nineteenth century'],explicacao:'Cassius Dio, the historian who documents the custom, writes that the ancient Greeks didn\'t know it and that the adoption was recent \u2014 and he gives two competing explanations for the order of the days, because not even he was sure. Even the ancient source thought the fashion was new.',fonte:'Cassius Dio, Roman History 37.18-19, 3rd c.'},'hist-porcentagem':{pergunta:'Which ancient source does the "compatibility percentage" between signs come from?',opcoes:['Ptolemy\'s Tetrabiblos','Dorotheus\' Carmen Astrologicum','The Alexandria papyri','None \u2014 there is no number in any ancient source'],explicacao:'Ptolemy, Dorotheus, M\u0101sh\u0101\'all\u0101h and Lilly were all combed through: no number, no "87%". What the tradition has is a four-step scale \u2014 and on it the opposition sits at the bottom, not at the top the apps tend to give it. The percentage is media convention from the twentieth century, with no documented inventor.',fonte:'Ptolemy, Tetrabiblos IV.7, 2nd c. (the ordinal scale); the percentage: 20th c., no identified author'},'hist-leao-coracao':{pergunta:'In the ancient list that tied signs to body parts, Leo matched what?',opcoes:['The heart, obviously','The flanks and the shoulder blades','The head','The feet'],explicacao:'"Leo = heart" is not in Manilius or in Ptolemy: in Manilius, author of the list of the twelve signs, Leo got the flanks and the shoulder blades \u2014 and Libra, which the market hands the kidneys, got the buttocks. The "heart" version can be dated: it shows up in print in Agrippa\'s Scale of Twelve, in 1533.',fonte:'Manilius, Astronomica II.453-465, 1st c. \xb7 Agrippa, Scale of Twelve, 1533'},'hist-signo-solar':{pergunta:'In ancient astrology, was the sun sign \u2014 "your sign" \u2014 the center of everything?',opcoes:['No \u2014 the Sun was one of the seven planets; what marked the individual was the Ascendant','Yes \u2014 always has been','Yes \u2014 Ptolemy says to start there','No \u2014 the center was Jupiter'],explicacao:'In the tradition, the significator of the individual is the Ascendant \u2014 and character, in Ptolemy, comes from Mercury and the Moon. The sun sign became the center for two reasons with a name and a date: Alan Leo, who needed to produce readings at scale, and the 1930 newspaper, which needed twelve boxes.',fonte:'Ptolemy, Tetrabiblos III.13, 2nd c. \xb7 Alan Leo, 1895-1917 \xb7 Naylor, 1930'},'hist-cuspide':{pergunta:'Is someone born "on the cusp" a bit of both signs?',opcoes:['Yes \u2014 it\'s ancient doctrine','Yes \u2014 but only on the water cusps','No \u2014 the sign boundary is an exact instant; what gets it wrong is the date table','No \u2014 "cusp" is a translation error'],explicacao:'The signs begin at the equinoxes and solstices, which are instants \u2014 Ptolemy writes that they\'re counted from those "and from no other source". What creates the legend is the fixed-date table in the almanacs, which really does get the boundaries wrong (29% of changeover days, measured). The answer isn\'t "I\'m both": it\'s calculating the Sun\'s longitude at the hour of birth \u2014 which is what this app does.',fonte:'Ptolemy, Tetrabiblos I.22, 2nd c. \xb7 the app\'s own measurement: 318 of 1,092 changeover days wrong by table'},'hist-5000-anos':{pergunta:'"Astrology is 5,000 years old." What\'s the honest count?',opcoes:['5,000 exactly, since the pyramids','Some 2,000 to 2,500 years of continuous textual tradition','10,000, since the caves','300 years, since the newspapers'],explicacao:'What\'s ~4,000 years old are Mesopotamian omens of state \u2014 a different thing, with no individual chart. The zodiac is ~2,450 years old, the oldest individual horoscope is from 410 BC, and the birth chart with an Ascendant is ~2,150. Two millennia and change of continuous texts is impressive enough \u2014 no need to inflate it.',fonte:'Synthesis of this app\'s primary-source research \u2014 tradition base, doc 10 \xa714.1'}}}},1646,[]);